230	PyObject *Autofuser::Codegen(PyObject *self, PyObject *args, PyObject *kwds) {
231	  (void)kwds;
232	  DumpGraphGuard guard;
233	  auto self_ = reinterpret_cast<Autofuser::Object *>(self);
234	
235	  PyObject *list_result_result = nullptr;
236	  if (PyArg_ParseTuple(args, "O", &list_result_result) == kPythonFail) {
237	    return PyErr_Format(PyExc_ValueError, "codegen requires a list of schedule result");
238	  }
239	
240	  auto fused_schedule_result = ge::PtrToPtr<PyObject, pyascir::FusedScheduledResult::Object>(list_result_result);
241	  codegen::CodegenResult result;
242	  af::Status ret = af::FAILED;
243	  try {
244	    ret = self_->codegen->GenerateForInductor(fused_schedule_result->fused_schedule_result, result);
245	  } catch (const std::runtime_error &e) {
246	    GELOGE(af::FAILED, "Caught a runtime_error: %s", e.what());
247	  }
248	  PY_ASSERT_SUCCESS(ret, "Codegen generate kernel failed or abort");
249	  DumpGraphGuard::ReInit();
250	  return Py_BuildValue("sss", result.tiling_data.c_str(), result.tiling.c_str(), result.kernel.c_str());
251	}
