349	PyObject *Schedule::ScheduleV1(PyObject *self_pyobject, PyObject *args, PyObject *kwds) {
350	  (void)kwds;
351	  ascir::AscGraphDumperContext::GetThreadLocalCtx().ClearAllWatchGraphs();
352	  auto self = reinterpret_cast<Schedule::Object *>(self_pyobject);
353	
354	  pyascir::HintGraph::Object *hint_graph = nullptr;
355	  if (PyArg_ParseTuple(args, "O!", &pyascir::HintGraph::type, &hint_graph) == kPythonFail) {
356	    return PyErr_Format(PyExc_ValueError, "Schedule requires a hint graph");
357	  }
358	  PyObject *fused_schedule_result_obj =
359	      pyascir::FusedScheduledResult::New(&pyascir::FusedScheduledResult::type, nullptr, nullptr);
360	  auto ret_init = pyascir::FusedScheduledResult::Init(fused_schedule_result_obj, nullptr, nullptr);
361	  GE_CHK_BOOL_RET_SPECIAL_STATUS(ret_init != 0, PyErr_Format(PyExc_TypeError, "FusedScheduledResult init fail"),
362	                                 "FusedScheduledResult init fail");
363	  auto fused_schedule_result = reinterpret_cast<pyascir::FusedScheduledResult::Object *>(fused_schedule_result_obj);
364	  PY_ASSERT_NOTNULL(hint_graph->graph);
365	  AssignDefaultIoIndex(*hint_graph->graph);
366	  if (self->optimizer->Optimize(*hint_graph->graph, fused_schedule_result->fused_schedule_result) != af::SUCCESS) {
367	    ascir::AscGraphDumperContext::GetThreadLocalCtx().DumpWatchedGraphs();
368	  }
369	  return Py_BuildValue("O", fused_schedule_result_obj);
