385	  GE_CHK_BOOL_RET_SPECIAL_STATUS(hint_compute_graph->compute_graph == nullptr,
386	                                 PyErr_Format(PyExc_RuntimeError, "compute_graph is nullptr"), "HintGraph new fail");
387	  auto ret_init = pyascir::FusedScheduledResult::Init(fused_schedule_result_obj, nullptr, nullptr);
388	  GE_CHK_BOOL_RET_SPECIAL_STATUS(ret_init != 0, PyErr_Format(PyExc_TypeError, "FusedScheduledResult init fail"),
389	                                 "FusedScheduledResult init fail");
390	
391	  auto fused_schedule_result = reinterpret_cast<pyascir::FusedScheduledResult::Object *>(fused_schedule_result_obj);
392	  auto ret = self->optimizer->Optimize(hint_compute_graph->compute_graph, fused_schedule_result->fused_schedule_result);
393	  if (ret != 0) {
394	    ascir::AscGraphDumperContext::GetThreadLocalCtx().DumpWatchedGraphs();
395	    ERROR_PRINT("Optimize fail ret %d", ret);
396	    return PyErr_Format(PyExc_RuntimeError, "Optimize fail");
397	  }
398	
399	  return Py_BuildValue("O", fused_schedule_result_obj);
