484	    if (tiling_lib_path_kwarg != nullptr && PyUnicode_Check(tiling_lib_path_kwarg)) {
485	      Py_ssize_t tiling_lib_path_len;
486	      const char *tiling_lib_path = PyUnicode_AsUTF8AndSize(tiling_lib_path_kwarg, &tiling_lib_path_len);
487	      options->tiling_lib_path = std::string(tiling_lib_path, tiling_lib_path_len);
488	    }
489	
490	    if (tiling_lib_codegen_symbol_kwarg != nullptr && PyUnicode_Check(tiling_lib_codegen_symbol_kwarg)) {
491	      Py_ssize_t tiling_lib_codegen_symbol_len;
492	      const char *tiling_lib_codegen_symbol =
493	          PyUnicode_AsUTF8AndSize(tiling_lib_codegen_symbol_kwarg, &tiling_lib_codegen_symbol_len);
494	      options->tiling_lib_codegen_symbol = std::string(tiling_lib_codegen_symbol, tiling_lib_codegen_symbol_len);
495	    }
496	  }
497	
498	  self->codegen = new codegen::Codegen(*options);
499	  delete options;
500	  return 0;
501	}
