503	af::Status CodeGen::HandleDeviceCodeGenForCVFusion(CodeGen::Object *self,
504	                                                   const ascir::FusedScheduledResult &fused_schedule_result,
505	                                                   PyObject *tiling_dict, PyObject *kernel_dict) {
506	  ascir::FusedScheduledResult ub_schedule_result = fused_schedule_result;
507	  ascir::FusedScheduledResult common_schedule_result = fused_schedule_result;
508	
509	  GE_ASSERT_SUCCESS(ascgen_utils::FilterCVFusionUBResult(ub_schedule_result));
510	  GE_ASSERT_SUCCESS(ascgen_utils::FilterCVFusionCommonResult(common_schedule_result));
511	
512	  // 生成UB模板的代码，存在没有UB模板的场景
513	  std::string ub_tiling_data;
514	  std::string ub_kernel;
515	  if (ascgen_utils::HasCubeUBFusedScheduled(ub_schedule_result)) {
516	    ub_tiling_data = self->codegen->GenerateTilingData(ub_schedule_result);
517	    af::Status ret = self->codegen->GenerateKernel(ub_schedule_result, ub_kernel, false);
518	    GE_CHK_STATUS_RET(ret, "codegen generate ub kernel fail");
519	  } else {
520	    GELOGI("Has no cube ub fused schedule result, no need to generate ub tiling data and kernel");
521	  }
522	
523	  // 生成兜底模板的代码，必须有兜底模板
524	  GE_ASSERT_TRUE(ascgen_utils::HasCubeCommonFusedScheduled(common_schedule_result));
525	  std::string common_tiling_data = self->codegen->GenerateTilingData(common_schedule_result);
526	  std::string common_kernel;
527	  af::Status ret = self->codegen->GenerateKernel(common_schedule_result, common_kernel, false);
528	  GE_CHK_STATUS_RET(ret, "codegen generate common kernel fail");
529	
530	  // 将结果添加到字典中
531	  PyObjectGuard g_ub_tiling(PyUnicode_FromString(ub_tiling_data.c_str()));
532	  PyObjectGuard g_common_tiling(PyUnicode_FromString(common_tiling_data.c_str()));
533	  PyObjectGuard g_ub_kernel(PyUnicode_FromString(ub_kernel.c_str()));
534	  PyObjectGuard g_common_kernel(PyUnicode_FromString(common_kernel.c_str()));
535	  if (g_ub_tiling.get() == nullptr || g_common_tiling.get() == nullptr || g_ub_kernel.get() == nullptr ||
536	      g_common_kernel.get() == nullptr || PyDict_SetItemString(tiling_dict, "ub", g_ub_tiling.get()) != 0 ||
537	      PyDict_SetItemString(tiling_dict, "common", g_common_tiling.get()) != 0 ||
538	      PyDict_SetItemString(kernel_dict, "ub", g_ub_kernel.get()) != 0 ||
539	      PyDict_SetItemString(kernel_dict, "common", g_common_kernel.get()) != 0) {
540	    return af::FAILED;
541	  }
542	
543	  return af::SUCCESS;
544	}
