661	PyObject *CodeGen::device_code_generator(PyObject *self_pyobject, PyObject *args, PyObject *kwds) {
662	  (void)kwds;
663	  DumpGraphGuard guard;
664	  auto self = reinterpret_cast<CodeGen::Object *>(self_pyobject);
665	
666	  PyObject *list_result_result = nullptr;
667	  if (PyArg_ParseTuple(args, "O", &list_result_result) == kPythonFail) {
668	    return PyErr_Format(PyExc_ValueError, "codegen param parse failed");
669	  }
670	
671	  if (PyObject_IsInstance(list_result_result, reinterpret_cast<PyObject *>(&pyascir::FusedScheduledResult::type)) !=
672	      kPythonSuccess) {
673	    return PyErr_Format(PyExc_TypeError, "device_code_generator requires FusedScheduledResult");
674	  }
675	  auto fused_schedule_result = reinterpret_cast<pyascir::FusedScheduledResult::Object *>(list_result_result);
676	
677	  // 创建字典用于存储不同模板的结果
678	  PyObject *tiling_dict = PyDict_New();
679	  if (tiling_dict == nullptr) {
680	    return PyErr_NoMemory();
681	  }
682	  GE_DISMISSABLE_GUARD(tiling_dict_guard, [tiling_dict]() { Py_DECREF(tiling_dict); });
683	
684	  PyObject *kernel_dict = PyDict_New();
685	  if (kernel_dict == nullptr) {
686	    return PyErr_NoMemory();
687	  }
688	  GE_DISMISSABLE_GUARD(kernel_dict_guard, [kernel_dict]() { Py_DECREF(kernel_dict); });
689	
690	  af::Status ret = af::FAILED;
691	
692	  try {
693	    // 如果是cv融合，需要过滤ub、兜底融合结果分别生成代码
694	    if (ascgen_utils::IsCubeFusedScheduled(fused_schedule_result->fused_schedule_result)) {
695	      ret =
696	          HandleDeviceCodeGenForCVFusion(self, fused_schedule_result->fused_schedule_result, tiling_dict, kernel_dict);
697	    } else {
698	      ret = HandleDeviceCodeGenForNonCVFusion(self, fused_schedule_result->fused_schedule_result, tiling_dict,
699	                                              kernel_dict);
700	    }
701	    GE_CHK_BOOL_RET_SPECIAL_STATUS(ret != af::SUCCESS, PyErr_Format(PyExc_ValueError, "codegen generate kernel fail"),
702	                                   "codegen generate kernel fail");
703	  } catch (const std::runtime_error &e) {
704	    GELOGE(af::FAILED, "Caught a runtime_error: %s", e.what());
705	    return PyErr_Format(PyExc_ValueError, "codegen generate kernel fail: %s", e.what());
706	  }
707	
708	  DumpGraphGuard::ReInit();
709	
710	  // 释放字典的所有权
711	  GE_DISMISS_GUARD(tiling_dict_guard);
712	  GE_DISMISS_GUARD(kernel_dict_guard);
713	  return Py_BuildValue("OO", tiling_dict, kernel_dict);
714	}
