716	PyObject *CodeGen::GenerateHostCodeResult(CodeGen::Object *self,
717	                                          pyascir::FusedScheduledResult::Object *fused_schedule_result,
718	                                          PyObject *shape_info_obj,
719	                                          const std::vector<std::vector<std::string>> &output_shape,
720	                                          const char *pgo_dir, const char *vector_core_num) {
721	  af::Status ret = af::FAILED;
722	  std::string infer_shape;
723	
724	  // 创建嵌套字典用于存储不同模板的结果
725	  // 外层字典的key是模板类型："common"、"ub"或"default"
726	  // 内层字典保持原始的key和value
727	  PyObject *py_tilings = PyDict_New();
728	  if (py_tilings == nullptr) {
729	    return PyErr_NoMemory();
730	  }
731	  GE_DISMISSABLE_GUARD(py_tilings_guard, [py_tilings]() { Py_DECREF(py_tilings); });
732	
733	  try {
734	    std::map<std::string, std::string> symbol_source_info;
735	    if (shape_info_obj != Py_None) {
736	      if (PyObject_IsInstance(shape_info_obj, reinterpret_cast<PyObject *>(&pyascir::ShapeInfo::type)) !=
737	          kPythonSuccess) {
738	        return PyErr_Format(PyExc_TypeError, "host_code_generator shape_info must be ShapeInfo type");
739	      }
740	      symbol_source_info = (reinterpret_cast<pyascir::ShapeInfo::Object *>(shape_info_obj))->shape_info;
741	    }
742	
743	    // 如果是cv融合，需要过滤ub、兜底融合结果分别生成代码
744	    if (ascgen_utils::IsCubeFusedScheduled(fused_schedule_result->fused_schedule_result)) {
745	      ret = HandleHostCodeGenForCVFusion(self, fused_schedule_result->fused_schedule_result, symbol_source_info,
746	                                         pgo_dir, vector_core_num, py_tilings);
747	    } else {
748	      ret = HandleHostCodeGenForNonCVFusion(self, fused_schedule_result->fused_schedule_result, symbol_source_info,
749	                                            pgo_dir, vector_core_num, py_tilings);
750	    }
751	    GE_CHK_BOOL_RET_SPECIAL_STATUS(ret != af::SUCCESS, PyErr_Format(PyExc_ValueError, "codegen generate host fail"),
752	                                   "codegen generate host fail");
753	
754	    infer_shape = self->codegen->GenerateInferShape(output_shape, symbol_source_info);
755	    // 释放字典的所有权
756	    GE_DISMISS_GUARD(py_tilings_guard);
757	    return Py_BuildValue("(NO)", py_tilings, PyUnicode_FromString(infer_shape.c_str()));
758	  } catch (const std::runtime_error &e) {
759	    GELOGE(af::FAILED, "Caught a runtime_error: %s", e.what());
760	    return PyErr_Format(PyExc_ValueError, "codegen generate host fail: %s", e.what());
761	  }
762	}
